#include <bits/stdc++.h>
using namespace std;

using vec = vector;
#define pb push_back
#define FOR(i, a, b) for(int i = (a); i < (b); i++)
#define FORE(i, a, b) for(int i = (a); i <= (b); i++)
#define FORD(i, a, b) for(int i = (a); i >= (b); i--)
const long long INF64 = 1e18;
typedef long long ll;

struct Edge {
  int from;
  int to;
  int flow;
  int cost;

  Edge() {};

  Edge(int _from, int _to, int _flow, int _cost) 
    : from(_from), to(_to), flow(_flow), cost(_cost) {};
};

vec<Edge> edges;

const int MAXN = 1e6 + 7;
vec<int> graph[MAXN];

ll totalCost = 0;
ll dist[MAXN];
int parent[MAXN];
int parentEdge[MAXN];
int inQueue[MAXN];

int sourceNode = MAXN - 2;
int sinkNode = MAXN - 1;

int residual(int edgeIdx) {
  return edges[edgeIdx].to - edges[edgeIdx].flow;
}

void runBellmanFord() {
  FOR(i, 0, MAXN) {
    dist[i] = INF64;
    parent[i] = -1;
    parentEdge[i] = -1;
    inQueue[i] = 0;
  }
  dist[sourceNode] = 0;
  queue<int> q;
  q.push(sourceNode);
  inQueue[sourceNode] = 1;
  while (!q.empty()) {
    int u = q.front(); q.pop();
    inQueue[u] = 0;
    for (auto eIdx : graph[u]) {
      if (!residual(eIdx)) continue;
      int cst = edges[eIdx].cost;
      int v = edges[eIdx].from;
      if (dist[v] > dist[u] + cst) {
        dist[v] = dist[u] + cst;
        parent[v] = u;
        parentEdge[v] = eIdx;
        if (!inQueue[v]) {
          inQueue[v] = 1;
          q.push(v);
        }
      }
    }
  }
}

void augment() {
  runBellmanFord();
  int cur = sinkNode;
  while (cur != sourceNode) {
    edges[parentEdge[cur]].flow++;
    edges[parentEdge[cur] ^ 1].flow--;
    cur = parent[cur];
  }
  totalCost += dist[sinkNode];
}

void addEdge(int u, int v, int cap, int cst) {
  graph[u].push_back(edges.size());
  edges.emplace_back(u, v, 0, cst);
  graph[v].push_back(edges.size());
  edges.emplace_back(v, u, cap, -cst);
}

int n, m, k, c, d;
const int T = 101;

void buildGraph() {
  scanf("%d %d %d %d %d", &n, &m, &k, &c, &d);
  for (int i = 0; i < k; i++) {
    int x; scanf("%d", &x);
    --x;
    addEdge(sourceNode, x, 1, 0);
  }
  for (int i = 0; i < T; i++) {
    addEdge(i * n, sinkNode, k, i * c);
  }
  for (int i = 0; i < m; i++) {
    int x, y; scanf("%d %d", &x, &y);
    --x; --y;
    for (int t = 0; t < T - 1; t++) {
      for (int j = 0; j < k; j++) {
        addEdge(x + t * n, y + t * n + n, 1, d * (j * 2 + 1));
      }
    }
    for (int t = 0; t < T - 1; t++) {
      for (int j = 0; j < k; j++) {
        addEdge(y + t * n, x + t * n + n, 1, d * (j * 2 + 1));
      }
    }
  }
}

void solve() {
  for (int i = 0; i < n; i++) {
    for (int t = 0; t < T - 1; t++) {
      addEdge(i + t * n, i + t * n + n, k, 0);
    }
  }
  for (int i = 0; i < k; i++) {
    augment();
  }
  printf("%lld\n", totalCost);
}

int main() {
  buildGraph();
  solve();
  return 0;
}
