import java.util.*;

public class Main {
    static class Edge {
        int from, to, flow, cost;
        Edge(int from, int to, int flow, int cost) {
            this.from = from;
            this.to = to;
            this.flow = flow;
            this.cost = cost;
        }
    }

    static final long INF64 = (long)1e18;
    static final int MAXN = 1000007;
    static List<Integer>[] graph = new ArrayList[MAXN];
    static List<Edge> edges = new ArrayList<>();
    static long totalCost = 0;
    static long[] dist = new long[MAXN];
    static int[] parent = new int[MAXN];
    static int[] parentEdge = new int[MAXN];
    static int[] inQueue = new int[MAXN];

    static int sourceNode = MAXN - 2;
    static int sinkNode = MAXN - 1;

    static int n, m, k, c, d;
    static final int T = 101;

    static int residual(int edgeIdx) {
        return edges.get(edgeIdx).to - edges.get(edgeIdx).flow;
    }

    static void runBellmanFord() {
        for (int i = 0; i < MAXN; i++) {
            dist[i] = INF64;
            parent[i] = -1;
            parentEdge[i] = -1;
            inQueue[i] = 0;
        }
        dist[sourceNode] = 0;
        Queue<Integer> q = new LinkedList<>();
        q.offer(sourceNode);
        inQueue[sourceNode] = 1;
        while (!q.isEmpty()) {
            int u = q.poll();
            inQueue[u] = 0;
            for (int eIdx : graph[u]) {
                if (residual(eIdx) == 0) continue;
                int cst = edges.get(eIdx).cost;
                int v = edges.get(eIdx).from;
                if (dist[v] > dist[u] + cst) {
                    dist[v] = dist[u] + cst;
                    parent[v] = u;
                    parentEdge[v] = eIdx;
                    if (inQueue[v] == 0) {
                        inQueue[v] = 1;
                        q.offer(v);
                    }
                }
            }
        }
    }

    static void augment() {
        runBellmanFord();
        int cur = sinkNode;
        while (cur != sourceNode) {
            Edge e = edges.get(parentEdge[cur]);
            e.flow++;
            edges.get(parentEdge[cur] ^ 1).flow--;
            cur = parent[cur];
        }
        totalCost += dist[sinkNode];
    }

    static void addEdge(int u, int v, int cap, int cst) {
        graph[u].add(edges.size());
        edges.add(new Edge(u, v, 0, cst));
        graph[v].add(edges.size());
        edges.add(new Edge(v, u, cap, -cst));
    }

    static void buildGraph(Scanner sc) {
        n = sc.nextInt();
        m = sc.nextInt();
        k = sc.nextInt();
        c = sc.nextInt();
        d = sc.nextInt();

        for (int i = 0; i < MAXN; i++) {
            graph[i] = new ArrayList<>();
        }

        for (int i = 0; i < k; i++) {
            int x = sc.nextInt();
            x--;
            addEdge(sourceNode, x, 1, 0);
        }

        for (int i = 0; i < T; i++) {
            addEdge(i * n, sinkNode, k, i * c);
        }

        for (int i = 0; i < m; i++) {
            int x = sc.nextInt();
            int y = sc.nextInt();
            x--;
            y--;
            for (int t = 0; t < T - 1; t++) {
                for (int j = 0; j < k; j++) {
                    addEdge(x + t * n, y + t * n + n, 1, d * (j * 2 + 1));
                }
            }
            for (int t = 0; t < T - 1; t++) {
                for (int j = 0; j < k; j++) {
                    addEdge(y + t * n, x + t * n + n, 1, d * (j * 2 + 1));
                }
            }
        }
    }

    static void solve() {
        for (int i = 0; i < n; i++) {
            for (int t = 0; t < T - 1; t++) {
                addEdge(i + t * n, i + t * n + n, k, 0);
            }
        }
        for (int i = 0; i < k; i++) {
            augment();
        }
        System.out.println(totalCost);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        buildGraph(sc);
        solve();
        sc.close();
    }
}
